// Expect columns: Client Name, Deadline Type, Due Date, Contact Email, Status, Last Reminder Sent
const today = new Date();
today.setHours(0,0,0,0);

const results = [];
for (const item of $input.all()) {
  const row = item.json;
  const dueDate = new Date(row['Due Date']);
  if (isNaN(dueDate.getTime())) continue;
  dueDate.setHours(0,0,0,0);

  const msPerDay = 1000 * 60 * 60 * 24;
  const daysUntilDue = Math.round((dueDate - today) / msPerDay);

  // Reminder milestones we care about
  const milestones = [30, 14, 7, 1];
  const isMilestone = milestones.includes(daysUntilDue);

  const lastReminder = row['Last Reminder Sent'] ? String(row['Last Reminder Sent']) : '';
  const alreadySentForThisMilestone = lastReminder === String(daysUntilDue);

  results.push({
    json: {
      ...row,
      daysUntilDue,
      isMilestone,
      alreadySentForThisMilestone,
      shouldSendReminder: isMilestone && !alreadySentForThisMilestone && row['Status'] !== 'Filed' && row['Status'] !== 'Cancelled'
    }
  });
}
return results;

// Build staged, deadline-specific email copy based on daysUntilDue and Deadline Type
const results = [];
for (const item of $input.all()) {
  const row = item.json;
  const days = row.daysUntilDue;
  const type = row['Deadline Type'];
  const client = row['Client Name'];
  const due = row['Due Date'];

  let urgency = 'Reminder';
  if (days <= 1) urgency = 'FINAL REMINDER – Due Tomorrow';
  else if (days <= 7) urgency = 'Urgent Reminder';
  else if (days <= 14) urgency = 'Reminder';
  else urgency = 'Advance Notice';

  const subject = `${urgency}: ${type} due for ${client} on ${due}`;
  const body = `Hi ${client},\n\n` +
    `This is a reminder that your ${type} deadline with HMRC is due on ${due} (${days} day${days === 1 ? '' : 's'} from now).\n\n` +
    `Please make sure any outstanding information or records are sent to us as soon as possible so we can file on time and avoid any late filing or late payment penalties.\n\n` +
    `If you have already sent everything through, thank you – you can disregard this message.\n\n` +
    `Kind regards,\nYour Accountancy Team`;

  results.push({ json: { ...row, emailSubject: subject, emailBody: body } });
}
return results;
